mkdir -p /tmp/model && cat > /tmp/model/model.cpp <<'EOF'
#include <iostream>
#include <tuple>
#include <map>
#include <string>
#include <cstdlib>
using K = std::tuple<int,int>;
int main(int argc, char* argv[]) {
    int n = 18;
    if (argc > 1) n = std::atoi(argv[1]);
    std::map<K,std::string> m;
    for (int i = 0; i < n; i++) m.insert({std::make_tuple(i,i*2), "value_" + std::to_string(i)});
    std::cout << m.size() << std::endl;
    auto k1 = std::make_tuple(3,6); auto k2 = std::make_tuple(5,10);
    std::cout << m.count(k1) << std::endl;
    std::cout << m.count(k2) << std::endl;
    std::cout << m[k1] << std::endl;
    m[k1] = "modified";
    std::cout << m[k1] << std::endl;
    std::cout << m.size() << std::endl;   // keys.size()
    std::cout << m.size() << std::endl;   // values.size()
    for (int i = 0; i < 4; i++) m.erase(std::make_tuple(i,i*2));
    std::cout << m.size() << std::endl;
    auto it = m.find(std::make_tuple(6,12));
    if (it != m.end()) std::cout << it->second << std::endl;
    auto lb = m.lower_bound(std::make_tuple(7,14));
    if (lb != m.end()) std::cout << std::get<0>(lb->first) << std::endl;
    auto ub = m.upper_bound(std::make_tuple(7,14));
    if (ub != m.end()) std::cout << std::get<0>(ub->first) << std::endl;
    std::map<K,std::string> m2;
    for (int i = 0; i < n/2; i++) m2.insert({std::make_tuple(i+10,(i+10)*2), "other_" + std::to_string(i)});
    for (auto& kv : m2) m[kv.first] = kv.second;   // update overwrites
    std::cout << m.size() << std::endl;
    std::cout << m.count(std::make_tuple(12,24)) << std::endl;
    auto range = m.equal_range(std::make_tuple(8,16));
    int count = 0;
    for (auto i2 = range.first; i2 != range.second; ++i2) count++;
    std::cout << count << std::endl;
    auto g = m.find(std::make_tuple(100,200));
    std::cout << (g != m.end() ? g->second : std::string("default")) << std::endl;
    m.clear();
    std::cout << m.size() << std::endl;
    std::cout << m.empty() << std::endl;
    return 0;
}
EOF
g++ -O2 -std=c++17 -o /tmp/model/model /tmp/model/model.cpp && echo "built"

