//! Two-level bucket storage: the engine behind [`SortedMap`](super::SortedMap).
//!
//! Entries live in a `Vec` of buckets, each bucket a `Vec<(K, V)>` kept in ascending
//! key order, and the buckets themselves ordered relative to one another. Locating a
//! key is a binary search over bucket tails followed by a binary search inside the
//! chosen bucket, so lookups stay `O(log n)` while insertion and removal only shift
//! elements within one bucket instead of across the whole collection.
//!
//! Two invariants hold at all times and everything else depends on them:
//!
//! 1. No bucket is ever empty. An empty bucket would make the "compare against the
//!    bucket's last key" binary search ill-defined and would let two different
//!    [`Pos`] values name the same element.
//! 2. Every bucket's keys are strictly less than the next bucket's keys.

/// Target bucket size. Buckets are split once they exceed twice this and merged with
/// a neighbour once they fall below half of it, so sizes stay within a constant factor.
pub const DEFAULT_LOAD_FACTOR: usize = 512;

/// A cursor position, i.e. a C++ iterator.
///
/// A position is *normalised*: either it addresses a live element
/// (`bucket < buckets.len()` and `offset < buckets[bucket].len()`), or it is the
/// past-the-end position `bucket == buckets.len(), offset == 0`. Because empty
/// buckets cannot exist, each element has exactly one representation, which is what
/// makes comparing two positions for equality meaningful.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Pos {
    pub bucket: usize,
    pub offset: usize,
}

pub struct Buckets<K, V> {
    buckets: Vec<Vec<(K, V)>>,
    len: usize,
    load: usize,
}

impl<K: Ord, V> Buckets<K, V> {
    pub fn new(load: usize) -> Self {
        Buckets {
            buckets: Vec::new(),
            len: 0,
            load: if load == 0 { 1 } else { load },
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn clear(&mut self) {
        self.buckets.clear();
        self.len = 0;
    }

    /// The past-the-end position, i.e. `end()`.
    pub fn end(&self) -> Pos {
        Pos {
            bucket: self.buckets.len(),
            offset: 0,
        }
    }

    /// The entry at `pos`, or `None` when `pos` is past the end.
    pub fn at(&self, pos: Pos) -> Option<(&K, &V)> {
        self.buckets
            .get(pos.bucket)
            .and_then(|bucket| bucket.get(pos.offset))
            .map(|entry| (&entry.0, &entry.1))
    }

    /// The position after `pos`, normalised. Advancing the end position is a no-op.
    pub fn advance(&self, pos: Pos) -> Pos {
        match self.buckets.get(pos.bucket) {
            None => pos,
            Some(bucket) => {
                let offset = pos.offset + 1;
                if offset < bucket.len() {
                    Pos {
                        bucket: pos.bucket,
                        offset,
                    }
                } else {
                    Pos {
                        bucket: pos.bucket + 1,
                        offset: 0,
                    }
                }
            }
        }
    }

    /// First position whose key is `>= key`.
    pub fn lower_bound(&self, key: &K) -> Pos {
        // The first bucket that can still hold such a key is the first whose last key
        // is `>= key`; every earlier bucket ends below `key` and so lies entirely below it.
        let bucket = self
            .buckets
            .partition_point(|bucket| bucket.last().map_or(true, |entry| entry.0 < *key));
        if bucket == self.buckets.len() {
            return self.end();
        }
        let offset = self.buckets[bucket].partition_point(|entry| entry.0 < *key);
        Pos { bucket, offset }
    }

    /// First position whose key is `> key`.
    pub fn upper_bound(&self, key: &K) -> Pos {
        let bucket = self
            .buckets
            .partition_point(|bucket| bucket.last().map_or(true, |entry| entry.0 <= *key));
        if bucket == self.buckets.len() {
            return self.end();
        }
        let offset = self.buckets[bucket].partition_point(|entry| entry.0 <= *key);
        Pos { bucket, offset }
    }

    /// Position of `key`, or the end position when it is absent.
    pub fn find(&self, key: &K) -> Pos {
        let pos = self.lower_bound(key);
        match self.at(pos) {
            Some((found, _)) if *found == *key => pos,
            _ => self.end(),
        }
    }

    pub fn get(&self, key: &K) -> Option<&V> {
        let pos = self.lower_bound(key);
        match self.at(pos) {
            Some((found, value)) if *found == *key => Some(value),
            _ => None,
        }
    }

    pub fn get_mut(&mut self, key: &K) -> Option<&mut V> {
        let pos = self.lower_bound(key);
        if self.matches(pos, key) {
            Some(&mut self.buckets[pos.bucket][pos.offset].1)
        } else {
            None
        }
    }

    /// Stores `value` under `key`, returning the value it displaced, if any.
    pub fn insert(&mut self, key: K, value: V) -> Option<V> {
        let pos = self.lower_bound(&key);
        if self.matches(pos, &key) {
            let slot = &mut self.buckets[pos.bucket][pos.offset].1;
            return Some(core::mem::replace(slot, value));
        }
        self.insert_at(pos, key, value);
        None
    }

    /// The value under `key`, inserting `make()` first when the key is absent.
    ///
    /// This is the C++ `operator[]`: reading a missing key materialises it.
    pub fn get_or_insert_with<F: FnOnce() -> V>(&mut self, key: K, make: F) -> &mut V {
        let pos = self.lower_bound(&key);
        let pos = if self.matches(pos, &key) {
            pos
        } else {
            self.insert_at(pos, key, make())
        };
        &mut self.buckets[pos.bucket][pos.offset].1
    }

    /// Removes `key`, returning its value when it was present.
    pub fn remove(&mut self, key: &K) -> Option<V> {
        let pos = self.lower_bound(key);
        if !self.matches(pos, key) {
            return None;
        }
        let (_, value) = self.buckets[pos.bucket].remove(pos.offset);
        self.len -= 1;
        self.rebalance(pos.bucket);
        Some(value)
    }

    pub fn iter<'a>(&'a self) -> impl Iterator<Item = (&'a K, &'a V)> + 'a {
        self.buckets
            .iter()
            .flat_map(|bucket| bucket.iter())
            .map(|entry| (&entry.0, &entry.1))
    }

    /// Whether `pos` addresses an entry keyed exactly by `key`.
    fn matches(&self, pos: Pos, key: &K) -> bool {
        match self.at(pos) {
            Some((found, _)) => *found == *key,
            None => false,
        }
    }

    /// Inserts a new entry at `pos`, which must be `lower_bound(&key)`, and reports where
    /// the entry ended up once any resulting split has been applied.
    fn insert_at(&mut self, pos: Pos, key: K, value: V) -> Pos {
        self.len += 1;
        if self.buckets.is_empty() {
            self.buckets.push(vec![(key, value)]);
            return Pos {
                bucket: 0,
                offset: 0,
            };
        }
        if pos.bucket == self.buckets.len() {
            // The key sorts after every entry, so it belongs at the tail of the last bucket.
            let bucket = self.buckets.len() - 1;
            let offset = self.buckets[bucket].len();
            self.buckets[bucket].push((key, value));
            return self.split_if_needed(bucket, offset);
        }
        self.buckets[pos.bucket].insert(pos.offset, (key, value));
        self.split_if_needed(pos.bucket, pos.offset)
    }

    /// Halves `bucket` if it has outgrown the load factor, translating `offset` into the
    /// position it occupies afterwards.
    fn split_if_needed(&mut self, bucket: usize, offset: usize) -> Pos {
        if self.buckets[bucket].len() > self.load * 2 {
            let mid = self.buckets[bucket].len() / 2;
            let tail = self.buckets[bucket].split_off(mid);
            self.buckets.insert(bucket + 1, tail);
            if offset >= mid {
                return Pos {
                    bucket: bucket + 1,
                    offset: offset - mid,
                };
            }
        }
        Pos { bucket, offset }
    }

    /// Restores the "no empty buckets, no runt buckets" invariant after a removal.
    fn rebalance(&mut self, bucket: usize) {
        if self.buckets[bucket].is_empty() {
            self.buckets.remove(bucket);
            return;
        }
        if self.buckets.len() < 2 || self.buckets[bucket].len() >= self.load / 2 {
            return;
        }
        // Fold the runt into its left neighbour (or, for the first bucket, fold the right
        // neighbour into it) so that key order across buckets is preserved either way.
        let target = if bucket > 0 { bucket - 1 } else { bucket };
        let donor = self.buckets.remove(target + 1);
        self.buckets[target].extend(donor);
        self.split_if_needed(target, 0);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn collect(store: &Buckets<i32, i32>) -> Vec<(i32, i32)> {
        store.iter().map(|(k, v)| (*k, *v)).collect()
    }

    /// Re-checks both structural invariants the search relies on.
    fn assert_invariants(store: &Buckets<i32, i32>) {
        let mut total = 0;
        let mut previous: Option<i32> = None;
        for bucket in &store.buckets {
            assert!(!bucket.is_empty(), "empty bucket");
            for entry in bucket {
                if let Some(last) = previous {
                    assert!(last < entry.0, "keys out of order: {} then {}", last, entry.0);
                }
                previous = Some(entry.0);
            }
            total += bucket.len();
        }
        assert_eq!(total, store.len());
    }

    #[test]
    fn ascending_inserts_split_and_stay_ordered() {
        let mut store = Buckets::new(4);
        for key in 0..200 {
            assert_eq!(store.insert(key, key * 10), None);
        }
        assert_invariants(&store);
        assert_eq!(collect(&store), (0..200).map(|k| (k, k * 10)).collect::<Vec<_>>());
    }

    #[test]
    fn descending_inserts_stay_ordered() {
        let mut store = Buckets::new(4);
        for key in (0..200).rev() {
            store.insert(key, key * 10);
        }
        assert_invariants(&store);
        assert_eq!(collect(&store), (0..200).map(|k| (k, k * 10)).collect::<Vec<_>>());
    }

    #[test]
    fn insert_replaces_and_reports_the_old_value() {
        let mut store = Buckets::new(4);
        store.insert(1, 100);
        assert_eq!(store.insert(1, 200), Some(100));
        assert_eq!(store.len(), 1);
        assert_eq!(store.get(&1), Some(&200));
    }

    #[test]
    fn bounds_agree_with_a_linear_scan() {
        let mut store = Buckets::new(3);
        // Even keys only, so every odd probe falls between two entries.
        for key in 0..100 {
            store.insert(key * 2, key);
        }
        let keys: Vec<i32> = (0..100).map(|k| k * 2).collect();
        for probe in -3..205 {
            let lower = store.lower_bound(&probe);
            let expected_lower = keys.iter().position(|k| *k >= probe);
            assert_eq!(store.at(lower).map(|(k, _)| *k), expected_lower.map(|i| keys[i]));
            assert_eq!(lower == store.end(), expected_lower.is_none());

            let upper = store.upper_bound(&probe);
            let expected_upper = keys.iter().position(|k| *k > probe);
            assert_eq!(store.at(upper).map(|(k, _)| *k), expected_upper.map(|i| keys[i]));
            assert_eq!(upper == store.end(), expected_upper.is_none());

            let found = store.find(&probe);
            assert_eq!(found != store.end(), keys.contains(&probe));
        }
    }

    #[test]
    fn advance_walks_every_entry_exactly_once() {
        let mut store = Buckets::new(3);
        for key in 0..50 {
            store.insert(key, key);
        }
        let mut pos = store.lower_bound(&i32::MIN);
        let mut walked = Vec::new();
        while pos != store.end() {
            walked.push(*store.at(pos).unwrap().0);
            pos = store.advance(pos);
        }
        assert_eq!(walked, (0..50).collect::<Vec<_>>());
        // Advancing past the end is saturating, never a panic.
        assert_eq!(store.advance(store.end()), store.end());
    }

    #[test]
    fn removal_keeps_invariants_and_empties_cleanly() {
        let mut store = Buckets::new(4);
        for key in 0..200 {
            store.insert(key, key);
        }
        for key in (0..200).step_by(3) {
            assert_eq!(store.remove(&key), Some(key));
            assert_invariants(&store);
        }
        assert_eq!(store.remove(&0), None);
        let survivors: Vec<i32> = (0..200).filter(|k| k % 3 != 0).collect();
        assert_eq!(collect(&store).into_iter().map(|(k, _)| k).collect::<Vec<_>>(), survivors);

        for key in survivors {
            store.remove(&key);
            assert_invariants(&store);
        }
        assert!(store.is_empty());
        assert_eq!(store.end(), Pos { bucket: 0, offset: 0 });
        assert_eq!(store.lower_bound(&7), store.end());
    }

    #[test]
    fn get_or_insert_with_materialises_missing_keys() {
        let mut store = Buckets::new(2);
        for key in [5, 1, 9, 3] {
            store.insert(key, key);
        }
        assert_eq!(*store.get_or_insert_with(7, || -1), -1);
        assert_eq!(store.len(), 5);
        *store.get_or_insert_with(7, || -99) = 42;
        assert_eq!(store.len(), 5);
        assert_eq!(store.get(&7), Some(&42));
        assert_invariants(&store);
    }

    /// The bucket layout must never be observable: it has to behave exactly like a
    /// sorted association list under an arbitrary mix of operations.
    #[test]
    fn matches_a_naive_model_under_random_operations() {
        let mut state = 0x2545_F491_4F6C_DD1Du64;
        let mut next = move || {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            state
        };
        for load in [1, 2, 3, 8, 64] {
            let mut store = Buckets::new(load);
            let mut model: Vec<(i32, i32)> = Vec::new();
            for step in 0..4000 {
                let key = (next() % 150) as i32;
                let slot = model.binary_search_by(|entry| entry.0.cmp(&key));
                if next() % 3 == 0 {
                    let removed = store.remove(&key);
                    match slot {
                        Ok(index) => assert_eq!(removed, Some(model.remove(index).1)),
                        Err(_) => assert_eq!(removed, None),
                    }
                } else {
                    let value = step;
                    let replaced = store.insert(key, value);
                    match slot {
                        Ok(index) => {
                            assert_eq!(replaced, Some(model[index].1));
                            model[index].1 = value;
                        }
                        Err(index) => {
                            assert_eq!(replaced, None);
                            model.insert(index, (key, value));
                        }
                    }
                }
                assert_eq!(store.len(), model.len());
            }
            assert_invariants(&store);
            assert_eq!(collect(&store), model);
            for probe in -2..152 {
                let expected = model.iter().position(|entry| entry.0 >= probe);
                assert_eq!(
                    store.at(store.lower_bound(&probe)).map(|(k, _)| *k),
                    expected.map(|i| model[i].0)
                );
                let expected = model.iter().position(|entry| entry.0 > probe);
                assert_eq!(
                    store.at(store.upper_bound(&probe)).map(|(k, _)| *k),
                    expected.map(|i| model[i].0)
                );
            }
        }
    }
}

