//! `SortedMap`: an ordered key/value map with the shape of the C++ original.
//!
//! | C++                        | Rust                                |
//! |----------------------------|-------------------------------------|
//! | `m.insert(k, v)`           | [`insert`](SortedMap::insert)       |
//! | `m[k]`                     | [`entry_or_default`](SortedMap::entry_or_default) |
//! | `m.contains(k)`            | [`contains_key`](SortedMap::contains_key) |
//! | `m.get(k, fallback)`       | [`get_or`](SortedMap::get_or)       |
//! | `m.erase(k)`               | [`remove`](SortedMap::remove)       |
//! | `m.size()` / `m.empty()`   | [`len`](SortedMap::len) / [`is_empty`](SortedMap::is_empty) |
//! | `m.find(k)` / `m.end()`    | [`find`](SortedMap::find) / [`end`](SortedMap::end) |
//! | `m.lower_bound(k)`         | [`lower_bound`](SortedMap::lower_bound) |
//! | `m.upper_bound(k)`         | [`upper_bound`](SortedMap::upper_bound) |
//! | `m.equal_range(k)`         | [`equal_range`](SortedMap::equal_range) |

use super::buckets::{Buckets, DEFAULT_LOAD_FACTOR};
use super::cursor::Cursor;

pub struct SortedMap<K, V> {
    store: Buckets<K, V>,
}

impl<K: Ord, V> SortedMap<K, V> {
    pub fn new() -> Self {
        SortedMap::with_load_factor(DEFAULT_LOAD_FACTOR)
    }

    /// Same map, with the bucket size tuned. Only the constant factors change.
    pub fn with_load_factor(load: usize) -> Self {
        SortedMap {
            store: Buckets::new(load),
        }
    }

    /// Number of entries. Mirrors `size()`.
    pub fn len(&self) -> usize {
        self.store.len()
    }

    /// Mirrors `empty()`.
    pub fn is_empty(&self) -> bool {
        self.store.is_empty()
    }

    pub fn clear(&mut self) {
        self.store.clear();
    }

    /// Stores `value` under `key`, returning the value it displaced, if any.
    pub fn insert(&mut self, key: K, value: V) -> Option<V> {
        self.store.insert(key, value)
    }

    pub fn contains_key(&self, key: &K) -> bool {
        self.store.get(key).is_some()
    }

    pub fn get(&self, key: &K) -> Option<&V> {
        self.store.get(key)
    }

    pub fn get_mut(&mut self, key: &K) -> Option<&mut V> {
        self.store.get_mut(key)
    }

    /// The value under `key`, or `fallback` when the key is absent. Mirrors the
    /// two-argument `get(key, fallback)`, which — unlike `operator[]` — inserts nothing.
    pub fn get_or<'a>(&'a self, key: &K, fallback: &'a V) -> &'a V {
        self.store.get(key).unwrap_or(fallback)
    }

    /// Removes `key`, returning its value when it was present. Mirrors `erase(key)`.
    pub fn remove(&mut self, key: &K) -> Option<V> {
        self.store.remove(key)
    }

    /// Entries in ascending key order.
    pub fn iter<'a>(&'a self) -> impl Iterator<Item = (&'a K, &'a V)> + 'a {
        self.store.iter()
    }

    /// Keys in ascending order. Mirrors `keys()`.
    pub fn keys(&self) -> Vec<K>
    where
        K: Clone,
    {
        self.store.iter().map(|(key, _)| key.clone()).collect()
    }

    /// Values ordered by their keys. Mirrors `values()`.
    pub fn values(&self) -> Vec<V>
    where
        V: Clone,
    {
        self.store.iter().map(|(_, value)| value.clone()).collect()
    }

    /// Cursor on `key`, or the end cursor when it is absent.
    pub fn find(&self, key: &K) -> Cursor<K, V> {
        Cursor::new(&self.store, self.store.find(key))
    }

    /// Cursor on the first entry whose key is `>= key`.
    pub fn lower_bound(&self, key: &K) -> Cursor<K, V> {
        Cursor::new(&self.store, self.store.lower_bound(key))
    }

    /// Cursor on the first entry whose key is `> key`.
    pub fn upper_bound(&self, key: &K) -> Cursor<K, V> {
        Cursor::new(&self.store, self.store.upper_bound(key))
    }

    /// The half-open cursor range covering `key`. Keys are unique, so it spans at most
    /// one entry — it is empty exactly when `key` is absent.
    pub fn equal_range(&self, key: &K) -> (Cursor<K, V>, Cursor<K, V>) {
        (self.lower_bound(key), self.upper_bound(key))
    }

    /// The past-the-end cursor. Mirrors `end()`.
    pub fn end(&self) -> Cursor<K, V> {
        Cursor::new(&self.store, self.store.end())
    }
}

impl<K: Ord, V: Default> SortedMap<K, V> {
    /// The value under `key`, inserting a default-constructed one first when the key is
    /// absent. This is C++ `operator[]` on a non-const map: merely reading a missing key
    /// through it grows the map, which the original program relies on.
    pub fn entry_or_default(&mut self, key: K) -> &mut V {
        self.store.get_or_insert_with(key, V::default)
    }
}

impl<K: Ord, V> Default for SortedMap<K, V> {
    fn default() -> Self {
        SortedMap::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn indexing_a_missing_key_inserts_a_default() {
        let mut map: SortedMap<(i32, i32), String> = SortedMap::new();
        assert_eq!(map.entry_or_default((3, 6)), "");
        assert_eq!(map.len(), 1);
        assert!(map.contains_key(&(3, 6)));

        *map.entry_or_default((3, 6)) = String::from("modified");
        assert_eq!(map.entry_or_default((3, 6)), "modified");
        assert_eq!(map.len(), 1);
    }

    #[test]
    fn get_or_does_not_insert() {
        let mut map: SortedMap<i32, String> = SortedMap::new();
        map.insert(1, String::from("one"));
        let fallback = String::from("default");
        assert_eq!(map.get_or(&1, &fallback), "one");
        assert_eq!(map.get_or(&2, &fallback), "default");
        assert_eq!(map.len(), 1);
    }

    #[test]
    fn keys_and_values_come_back_sorted_and_aligned() {
        let mut map: SortedMap<(i32, i32), String> = SortedMap::with_load_factor(2);
        for key in [3, 1, 4, 1, 5, 9, 2, 6] {
            map.insert((key, key * 2), format!("value_{}", key));
        }
        let keys = map.keys();
        let values = map.values();
        assert_eq!(keys, vec![(1, 2), (2, 4), (3, 6), (4, 8), (5, 10), (6, 12), (9, 18)]);
        assert_eq!(values.len(), keys.len());
        for (key, value) in keys.iter().zip(values.iter()) {
            assert_eq!(value, &format!("value_{}", key.0));
        }
    }

    #[test]
    fn tuple_keys_order_lexicographically_like_std_tuple() {
        let mut map: SortedMap<(i32, i32), i32> = SortedMap::with_load_factor(2);
        for key in [(1, 9), (0, 5), (1, 2), (-1, 0), (0, 4)] {
            map.insert(key, 0);
        }
        assert_eq!(map.keys(), vec![(-1, 0), (0, 4), (0, 5), (1, 2), (1, 9)]);
    }

    #[test]
    fn cursors_behave_like_map_iterators() {
        let mut map: SortedMap<(i32, i32), String> = SortedMap::with_load_factor(2);
        for key in 0..10 {
            map.insert((key, key * 2), format!("value_{}", key));
        }

        assert!(map.find(&(6, 12)) != map.end());
        assert_eq!(map.find(&(6, 12)).value().map(String::as_str), Some("value_6"));
        assert!(map.find(&(6, 13)) == map.end());
        assert_eq!(map.find(&(6, 13)).value(), None);
        assert!(map.end().is_end());

        assert_eq!(map.lower_bound(&(7, 14)).key(), Some(&(7, 14)));
        assert_eq!(map.upper_bound(&(7, 14)).key(), Some(&(8, 16)));
        // A key that is absent: both bounds land on the following entry.
        assert_eq!(map.lower_bound(&(7, 0)).key(), Some(&(7, 14)));
        assert_eq!(map.upper_bound(&(7, 0)).key(), Some(&(7, 14)));
        // Past the last key: both bounds are the end.
        assert!(map.lower_bound(&(10, 0)) == map.end());
        assert!(map.upper_bound(&(9, 18)) == map.end());

        // Walking the whole map with a cursor visits everything in order.
        let mut cursor = map.lower_bound(&(i32::MIN, i32::MIN));
        let mut walked = Vec::new();
