//! C and C++ runtime behaviours the port has to reproduce byte for byte.
//!
//! Rust's equivalents of these are deliberately stricter than C's, so the differences are
//! observable and the originals have to be spelled out.

/// `std::atoi` on a decimal string, including its edge cases.
///
/// `str::parse::<i32>()` is not a substitute: it rejects everything `atoi` shrugs off.
/// `atoi` skips leading whitespace, takes an optional sign, consumes as many decimal digits
/// as it finds, and stops at the first byte that is not one — yielding `0` when there were no
/// digits at all. So `"  12"`, `"+5"`, `"7abc"`, `"12.9"` and `"1e3"` parse to 12, 5, 7, 12
/// and 1, while `"abc"`, `"0x10"` and `""` all parse to 0.
///
/// Out-of-range input matters too, because glibc implements `atoi(s)` as
/// `(int)strtol(s, nullptr, 10)`: the magnitude saturates at `LONG_MAX`/`LONG_MIN` and is
/// then truncated to 32 bits. That is why `"2147483648"` comes out as `-2147483648`,
/// `"4294967296"` as `0`, `"9999999999999999999999"` as `-1`, and its negation as `0`.
pub fn atoi(text: &str) -> i32 {
    let bytes = text.as_bytes();
    let mut index = 0;

    while index < bytes.len() && is_space(bytes[index]) {
        index += 1;
    }

    let negative = match bytes.get(index) {
        Some(b'-') => {
            index += 1;
            true
        }
        Some(b'+') => {
            index += 1;
            false
        }
        _ => false,
    };

    // Accumulate the magnitude, clamping at the limit `strtol` would report for this sign.
    let limit: u64 = if negative {
        1u64 << 63 // -(i64::MIN) does not fit in an i64, but its magnitude fits here.
    } else {
        i64::MAX as u64
    };
    let mut magnitude: u64 = 0;
    while let Some(digit) = bytes.get(index).and_then(|byte| decimal_digit(*byte)) {
        magnitude = magnitude
            .checked_mul(10)
            .and_then(|scaled| scaled.checked_add(digit))
            .filter(|candidate| *candidate <= limit)
            .unwrap_or(limit);
        index += 1;
    }

    // `magnitude as i64` maps the negative clamp 2^63 onto `i64::MIN`, whose negation
    // wraps back to itself — exactly what the C cast chain produces.
    let wide = magnitude as i64;
    let value = if negative { wide.wrapping_neg() } else { wide };
    value as i32
}

/// The bytes C's `isspace` accepts in the default locale.
fn is_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

fn decimal_digit(byte: u8) -> Option<u64> {
    match byte {
        b'0'..=b'9' => Some(u64::from(byte - b'0')),
        _ => None,
    }
}

/// How `std::cout << bool` renders: `1` or `0`, never `true` or `false`.
pub fn ostream_bool(value: bool) -> u8 {
    u8::from(value)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn plain_numbers() {
        assert_eq!(atoi("0"), 0);
        assert_eq!(atoi("18"), 18);
        assert_eq!(atoi("007"), 7);
        assert_eq!(atoi("+5"), 5);
        assert_eq!(atoi("-5"), -5);
        assert_eq!(atoi("-0"), 0);
        assert_eq!(atoi("2147483647"), i32::MAX);
        assert_eq!(atoi("-2147483648"), i32::MIN);
    }

    #[test]
    fn leading_whitespace_is_skipped() {
        assert_eq!(atoi(" 12"), 12);
        assert_eq!(atoi("\t9"), 9);
        assert_eq!(atoi("\n\r\u{b}\u{c} 3"), 3);
        assert_eq!(atoi("  -3"), -3);
    }

    #[test]
    fn parsing_stops_at_the_first_non_digit() {
        assert_eq!(atoi("7abc"), 7);
        assert_eq!(atoi("12.9"), 12);
        assert_eq!(atoi("1e3"), 1);
        assert_eq!(atoi("5 "), 5);
        assert_eq!(atoi("0x10"), 0);
    }

    #[test]
    fn input_without_digits_is_zero() {
        assert_eq!(atoi(""), 0);
        assert_eq!(atoi("abc"), 0);
        assert_eq!(atoi("."), 0);
        assert_eq!(atoi("+-3"), 0);
        assert_eq!(atoi("-"), 0);
        assert_eq!(atoi("   "), 0);
        // Non-UTF-8 bytes reach us as U+FFFD, which is not a digit — the same stop that
        // C's atoi makes on a byte above 0x7f.
        assert_eq!(atoi("\u{fffd}5"), 0);
    }

    #[test]
    fn out_of_range_input_saturates_then_truncates() {
        assert_eq!(atoi("2147483648"), -2147483648);
        assert_eq!(atoi("4294967296"), 0);
        assert_eq!(atoi("9223372036854775807"), -1); // i64::MAX truncated
        assert_eq!(atoi("9999999999999999999999"), -1); // clamped to i64::MAX, then truncated
        assert_eq!(atoi("-9999999999999999999999"), 0); // clamped to i64::MIN, then truncated
        assert_eq!(atoi("-9223372036854775808"), 0);
        // Long digit runs must clamp rather than wrap around u64.
        assert_eq!(atoi(&"9".repeat(100)), -1);
        assert_eq!(atoi(&format!("-{}", "9".repeat(100))), 0);
        assert_eq!(atoi(&format!("{}5", "0".repeat(100))), 5);
    }

    #[test]
    fn bools_render_as_digits() {
        assert_eq!(ostream_bool(true).to_string(), "1");
        assert_eq!(ostream_bool(false).to_string(), "0");
    }
}

