//! Port of `tests/test18.cpp`: exercises `SortedMap` keyed on a two-element tuple.
//!
//! Output is byte-for-byte identical to the C++ original for every argument vector,
//! including the ones `std::atoi` merely tolerates.

mod compat;
mod sortedcontainers;

use self::compat::{atoi, ostream_bool};
use self::sortedcontainers::{update, SortedMap};

/// The original keys on `std::tuple<int, int>`; a Rust tuple orders lexicographically the
/// same way, so the iteration order carries over unchanged.
type Key = (i32, i32);

fn main() {
    let mut n: i32 = 18;
    // `argv[1]`, parsed the way `std::atoi` would. `args_os` rather than `args` because the
    // C++ program accepts arbitrary bytes here while `args` panics on non-UTF-8 input; the
    // lossy decoding is equivalent for `atoi`, which stops at the first byte that is not a
    // digit either way.
    if let Some(argument) = std::env::args_os().nth(1) {
        n = atoi(&argument.to_string_lossy());
    }

    let mut m: SortedMap<Key, String> = SortedMap::new();
    for i in 0..n {
        m.insert((i, i * 2), format!("value_{}", i));
    }

    println!("{}", m.len());

    let test_key1: Key = (3, 6);
    let test_key2: Key = (5, 10);

    println!("{}", ostream_bool(m.contains_key(&test_key1)));
    println!("{}", ostream_bool(m.contains_key(&test_key2)));

    // `m[test_key1]` on a missing key inserts an empty string and returns it, so this both
    // prints a blank line and grows the map — which the `keys()` count below reflects.
    println!("{}", m.entry_or_default(test_key1));

    *m.entry_or_default(test_key1) = String::from("modified");
    println!("{}", m.entry_or_default(test_key1));

    let keys = m.keys();
    let values = m.values();

    println!("{}", keys.len());
    println!("{}", values.len());

    for i in 0..4 {
        m.remove(&(i, i * 2));
    }

    println!("{}", m.len());

    // Each of the next three lines is printed only when the lookup lands on an entry, so
    // the total number of output lines varies with `n`.
    if let Some(value) = m.find(&(6, 12)).value() {
        println!("{}", value);
    }

    if let Some(key) = m.lower_bound(&(7, 14)).key() {
        println!("{}", key.0);
    }

    if let Some(key) = m.upper_bound(&(7, 14)).key() {
        println!("{}", key.0);
    }

    let mut m2: SortedMap<Key, String> = SortedMap::new();
    for i in 0..n / 2 {
        m2.insert((i + 10, (i + 10) * 2), format!("other_{}", i));
    }

    update(&mut m, &m2);

    println!("{}", m.len());
    println!("{}", ostream_bool(m.contains_key(&(12, 24))));

    let (first, last) = m.equal_range(&(8, 16));
    let mut cursor = first;
    let mut count = 0;
    while cursor != last {
        count += 1;
        cursor.advance();
    }
    println!("{}", count);

    let fallback = String::from("default");
    println!("{}", m.get_or(&(100, 200), &fallback));

    m.clear();

    println!("{}", m.len());
    println!("{}", ostream_bool(m.is_empty()));
}

