//! A pure-`std` reimplementation of the `sortedcontainers` C++ header.
//!
//! The layout follows the C++ library of the same name (itself a port of Python's
//! `sortedcontainers`): entries are held in a two-level list of buckets rather than in a
//! search tree, so ordered lookups are `O(log n)` while insertion and removal shift
//! elements within a single bucket instead of across the whole collection.
//!
//! * [`buckets`] — the storage engine and its positions.
//! * [`cursor`] — [`Cursor`], the stand-in for a C++ iterator.
//! * [`sorted_map`] — [`SortedMap`], the public container.

// This module is a library: it deliberately offers the whole container API, and re-exports
// all of it, even though the program in `test18.rs` exercises only part of it.
#![allow(dead_code, unused_imports)]

pub mod buckets;
pub mod cursor;
pub mod sorted_map;

pub use self::cursor::Cursor;
pub use self::sorted_map::SortedMap;

/// Copies every entry of `source` into `target`, overwriting keys that already exist.
///
/// Mirrors the free function `sortedcontainers::update(target, source)`, whose
/// last-write-wins behaviour the original program depends on.
pub fn update<K, V>(target: &mut SortedMap<K, V>, source: &SortedMap<K, V>)
where
    K: Ord + Clone,
    V: Clone,
{
    for (key, value) in source.iter() {
        target.insert(key.clone(), value.clone());
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn update_merges_and_overwrites() {
        let mut target: SortedMap<(i32, i32), String> = SortedMap::with_load_factor(2);
        for key in 0..6 {
            target.insert((key, key * 2), format!("value_{}", key));
        }
        let mut source: SortedMap<(i32, i32), String> = SortedMap::with_load_factor(2);
        for key in 4..9 {
            source.insert((key, key * 2), format!("other_{}", key));
        }

        update(&mut target, &source);

        assert_eq!(target.len(), 9);
        // Keys only in `target` keep their value; overlapping keys take `source`'s.
        assert_eq!(target.get(&(3, 6)).map(String::as_str), Some("value_3"));
        assert_eq!(target.get(&(4, 8)).map(String::as_str), Some("other_4"));
        assert_eq!(target.get(&(8, 16)).map(String::as_str), Some("other_8"));
        assert_eq!(source.len(), 5, "the source must be left untouched");
    }

    #[test]
    fn update_from_an_empty_source_is_a_no_op() {
        let mut target: SortedMap<i32, i32> = SortedMap::new();
        target.insert(1, 1);
        update(&mut target, &SortedMap::new());
        assert_eq!(target.len(), 1);
    }
}

//! Cursors, the Rust stand-in for the C++ container's iterators.
//!
//! The original code treats an iterator as a comparable handle into the map:
//!
//! ```cpp
//! auto it = m.find(key);
//! if (it != m.end()) { use(it->second); }
//! for (auto it = range.first; it != range.second; ++it) { ... }
//! ```
//!
//! [`Cursor`] keeps that shape — it compares with `==`/`!=`, steps with
//! [`advance`](Cursor::advance), and reads through [`key`](Cursor::key) /
//! [`value`](Cursor::value) — while making the past-the-end case unrepresentable as a
//! read: dereferencing the end cursor yields `None` instead of undefined behaviour.

use super::buckets::{Buckets, Pos};

pub struct Cursor<'a, K, V> {
    store: &'a Buckets<K, V>,
    pos: Pos,
}

impl<'a, K: Ord, V> Cursor<'a, K, V> {
    pub(crate) fn new(store: &'a Buckets<K, V>, pos: Pos) -> Self {
        Cursor { store, pos }
    }

    /// Whether this is the past-the-end cursor, i.e. `it == m.end()`.
    pub fn is_end(&self) -> bool {
        self.store.at(self.pos).is_none()
    }

    /// The key under the cursor, or `None` at the end. Mirrors `it->first`.
    pub fn key(&self) -> Option<&'a K> {
        self.store.at(self.pos).map(|(key, _)| key)
    }

    /// The value under the cursor, or `None` at the end. Mirrors `it->second`.
    pub fn value(&self) -> Option<&'a V> {
        self.store.at(self.pos).map(|(_, value)| value)
    }

    /// Both halves at once. Mirrors `*it`.
    pub fn entry(&self) -> Option<(&'a K, &'a V)> {
        self.store.at(self.pos)
    }

    /// Steps to the next entry. Mirrors `++it`, except that advancing the end cursor
    /// leaves it at the end rather than running off the container.
    pub fn advance(&mut self) {
        self.pos = self.store.advance(self.pos);
    }
}

// The following impls are written out by hand rather than derived: deriving would
// demand `K: Clone`/`K: PartialEq` and friends from the element types, when a cursor is
// only ever a borrow plus a position.

impl<'a, K, V> Clone for Cursor<'a, K, V> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<'a, K, V> Copy for Cursor<'a, K, V> {}

impl<'a, K, V> PartialEq for Cursor<'a, K, V> {
    /// Cursors are equal when they point at the same slot of the same map. Positions are
    /// normalised, so equal slots always compare equal; cursors into different maps never do.
    fn eq(&self, other: &Self) -> bool {
        std::ptr::eq(self.store, other.store) && self.pos == other.pos
    }
}

impl<'a, K, V> Eq for Cursor<'a, K, V> {}

impl<'a, K, V> std::fmt::Debug for Cursor<'a, K, V> {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        f.debug_struct("Cursor")
            .field("bucket", &self.pos.bucket)
            .field("offset", &self.pos.offset)
            .finish()
    }
}
